import React from 'react';

function MyTickets({ bookings = [], movies = [], showtimes = [], seats = [] }) {
  const findShowtime = (id) => showtimes.find(s => s.id === id) || {};
  const findMovie = (movie_id) => movies.find(m => m.id === movie_id) || {};
  const findSeat = (id) => seats.find(s => s.id === id) || {};

  return (
    <div>
      <h3 className="fw-bold mb-3" style={{ color: '#7c3aed' }}>Vé của tôi</h3>
      <div className="row">
        {bookings.length === 0 && <div className="col-12 text-muted">Bạn chưa có vé nào.</div>}

        {bookings.map(b => {
          const st = findShowtime(b.showtime_id);
          const movie = findMovie(st.movie_id);
          const seat = findSeat(b.seat_id);
          return (
            <div key={b.id} className="col-12 col-md-6 mb-3">
              <div className="card p-3 shadow-sm" style={{ borderRadius: 12 }}>
                <div className="d-flex justify-content-between align-items-start">
                  <div>
                    <div className="fw-bold">{movie.title}</div>
                    <div className="text-secondary small">{st.show_date} • {st.show_time}</div>
                    <div className="mt-2">Ghế: <strong>{seat.seat_number}</strong></div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div className="badge" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', color: 'white', padding: '8px 12px', borderRadius: 8 }}>Đã thanh toán</div>
                    <div className="mt-3" style={{ width: 100, height: 100, background: '#f3f4f6', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8 }}>QR {String(b.id).slice(2,8)}</div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default MyTickets;
